{"yol":"telefon.js","icerik":"export function telefonNormalle(numara) {
  // If it starts with +90, extract the digits after it
  if (numara.startsWith('+90')) {
    const rakamlar = numara.replace(/\D/g, '')
    return `+90${rakamlar.slice(2)}`
  }
  // Otherwise, just extract all digits and prepend +90
  const rakamlar = numara.replace(/\D/g, '')
  return `+90${rakamlar.slice(1)}`
}"}
